/* Tree Select: dependency-free checkbox and radio trees. */
(function(g){"use strict";let instance=0;
class TreeSelect{
constructor(target,opt={}){this.el=typeof target==="string"?document.querySelector(target):target;if(!this.el)throw Error("TreeSelect: container not found");this.opt=opt;this.mode=opt.mode==="radio"?"radio":"checkbox";this.name=opt.name||"";this.uid="tree-"+(++instance);this.selected=new Set();this.manual=new Set();this.closed=new Set();this.query="";this.setModel(opt.data||[]);let start=opt.selectedIds|| (opt.value==null?[]:[opt.value]);this.load(start);this.draw()}
setModel(data){this.map=new Map();this.roots=[];let id=this.opt.idKey||"ID",text=this.opt.textKey||"MaterialObjectTypeName",parent=this.opt.parentKey||"ParentID",kids=this.opt.childrenKey||"children";const add=(raw,p)=>{let key=String(raw[id]);if(raw[id]==null||this.map.has(key))throw Error("TreeSelect: invalid/duplicate ID "+key);let n={id:raw[id],key,name:String(raw[text]??""),parent:p,children:[],raw};this.map.set(key,n);if(p)p.children.push(n);else this.roots.push(n);return n};if(data.some(x=>Array.isArray(x[kids]))){let walk=(x,p)=>{let n=add(x,p);(x[kids]||[]).forEach(c=>walk(c,n))};data.forEach(x=>walk(x,null))}else{data.forEach(x=>{let key=String(x[id]);if(x[id]==null||this.map.has(key))throw Error("TreeSelect: invalid/duplicate ID "+key);this.map.set(key,{id:x[id],key,name:String(x[text]??""),parent:null,children:[],raw:x})});for(let n of this.map.values()){let p=n.raw[parent]==null?null:this.map.get(String(n.raw[parent]));if(p){n.parent=p;p.children.push(n)}else this.roots.push(n)}}let visiting=new Set(),done=new Set();let visit=n=>{if(visiting.has(n.key))throw Error("TreeSelect: cycle "+n.key);if(done.has(n.key))return;visiting.add(n.key);n.children.forEach(visit);visiting.delete(n.key);done.add(n.key)};this.map.forEach(visit)}
load(ids){this.selected.clear();for(let id of (Array.isArray(ids)?ids:[ids])){let key=String(id);if(this.map.has(key)){if(this.mode==="radio")this.selected.clear();this.selected.add(key)}}}
make(tag,cls,txt){let e=document.createElement(tag);if(cls)e.className=cls;if(txt!==undefined)e.textContent=txt;return e}
draw(){this.el.replaceChildren();this.el.classList.add("mts");let bar=this.make("div","mts-bar");if(this.opt.search!==false){this.search=this.make("input","mts-search");this.search.type="search";this.search.placeholder=this.opt.searchPlaceholder||"Поиск по дереву…";this.search.setAttribute("aria-label","Поиск");this.search.value=this.query;this.search.addEventListener("input",()=>this.setSearch(this.search.value));bar.append(this.search)}this.count=this.make("span","mts-count");bar.append(this.count);let clear=this.make("button","mts-clear","Сбросить");clear.type="button";clear.addEventListener("click",()=>this.clear());bar.append(clear);this.el.append(bar);this.list=this.make("ul","mts-list");this.roots.forEach(n=>this.list.append(this.node(n)));this.el.append(this.list);this.empty=this.make("p","mts-empty","Ничего не найдено");this.el.append(this.empty);this.refresh()}
node(n){let li=this.make("li","mts-item"),row=this.make("div","mts-row");n.li=li;n.row=row;let children=n.children.length>0;if(children){let btn=this.make("button","mts-toggle","⌄");btn.type="button";btn.title="Свернуть / развернуть";btn.addEventListener("click",()=>{this.closed.has(n.key)?this.closed.delete(n.key):this.closed.add(n.key);this.visibility()});n.toggle=btn;row.append(btn)}else row.append(this.make("span","mts-space"));if(this.mode==="checkbox"){if(children){let b=this.make("button","mts-branch","☑");b.type="button";b.title="Отметить / снять только вложенные";b.setAttribute("aria-label","Отметить вложенные: "+n.name);b.addEventListener("click",()=>{let keys=this.descendants(n);let checked=keys.every(k=>this.selected.has(k));keys.forEach(k=>{if(checked){this.selected.delete(k);this.manual.delete(k)}else{this.selected.add(k);this.manual.add(k)}});this.changed()});n.branch=b;row.append(b)}else row.append(this.make("span","mts-space"))}let input=this.make("input","mts-input");input.type=this.mode;input.id=this.uid+"-"+this.map.size+"-"+n.key.replace(/[^a-zA-Z0-9_-]/g,"_");input.value=n.key;if(this.name)input.name=this.name;input.addEventListener("change",()=>{if(this.mode==="radio")this.setSelected(n.id);else this.setChecked([n.id],input.checked,{manual:true})});n.input=input;let label=this.make("label","mts-label",n.name);label.htmlFor=input.id;n.label=label;row.append(input,label);li.append(row);if(children){let ul=this.make("ul","mts-children");n.ul=ul;n.children.forEach(c=>ul.append(this.node(c)));li.append(ul)}return li}
descendants(n){let out=[];let go=x=>x.children.forEach(c=>{out.push(c.key);go(c)});go(n);return out}
refresh(){for(let n of this.map.values()){n.input.checked=this.selected.has(n.key);n.row.classList.toggle("mts-selected",this.selected.has(n.key));if(n.branch){let keys=this.descendants(n);n.branch.classList.toggle("mts-branch-all",keys.every(k=>this.selected.has(k)));n.branch.classList.toggle("mts-branch-some",keys.some(k=>this.selected.has(k))&&!keys.every(k=>this.selected.has(k)))}}this.count.textContent=this.mode==="radio"?(this.selected.size?"Выбрано: 1":"Не выбрано"):"Выбрано: "+this.selected.size;this.visibility()}
visibility(){let q=this.query.toLocaleLowerCase().trim(),matches=0;let walk=(n,ancestor)=>{let self=!!q&&n.name.toLocaleLowerCase().includes(q);if(self)matches++;let descendant=false;for(let c of n.children)if(walk(c,ancestor||self))descendant=true;let visible=!q||ancestor||self||descendant;n.li.hidden=!visible;if(n.ul)n.ul.hidden=q?false:this.closed.has(n.key);if(n.toggle)n.toggle.textContent=q||!this.closed.has(n.key)?"⌄":"›";n.label.replaceChildren();if(self){let idx=n.name.toLocaleLowerCase().indexOf(q);n.label.append(document.createTextNode(n.name.slice(0,idx)));let mark=this.make("mark","",n.name.slice(idx,idx+q.length));n.label.append(mark,document.createTextNode(n.name.slice(idx+q.length)))}else n.label.textContent=n.name;return visible};this.roots.forEach(n=>walk(n,false));this.list.hidden=!!q&&!matches;this.empty.hidden=!q||!!matches}
changed(){this.refresh();let selected=this.getSelected();if(typeof this.opt.onChange==="function")this.opt.onChange(selected,this);this.el.dispatchEvent(new CustomEvent("tree-select:change",{bubbles:true,detail:{value:selected,mode:this.mode,name:this.name}}))}
getSelected(){let a=[...this.selected].map(k=>this.map.get(k).id);return this.mode==="radio"?(a[0]??null):a}
getSelectedIds(){let a=this.getSelected();return this.mode==="radio"?(a==null?[]:[a]):a}
getManuallySelected(){return [...this.manual].map(k=>this.map.get(k).id)}
setChecked(ids,checked=true,opt={}){if(this.mode!=="checkbox")throw Error("Only checkbox mode");for(let id of ids){let n=this.map.get(String(id));if(!n)continue;let keys=opt.cascade?[n.key,...this.descendants(n)]:[n.key];keys.forEach(k=>{checked?this.selected.add(k):this.selected.delete(k);if(opt.manual)checked?this.manual.add(k):this.manual.delete(k)})}this.changed()}
setSelected(v){let ids=this.mode==="radio"?(v==null?[]:[Array.isArray(v)?v[0]:v]):v;if(!Array.isArray(ids))throw Error("Expected array");this.load(ids);this.manual.clear();this.changed()}
selectBranch(id,checked=true){if(this.mode!=="checkbox")throw Error("Only checkbox mode");let n=this.map.get(String(id));if(n)this.setChecked(this.descendants(n),checked,{manual:true})}
checkAll(checked=true){if(this.mode!=="checkbox")throw Error("Only checkbox mode");this.selected=new Set(checked?this.map.keys():[]);this.manual=new Set(this.selected);this.changed()}
clear(){this.selected.clear();this.manual.clear();this.changed()}
setSearch(q){this.query=String(q??"");if(this.search&&this.search.value!==this.query)this.search.value=this.query;this.visibility()}
expandAll(){this.closed.clear();this.visibility()}
collapseAll(){this.map.forEach(n=>{if(n.children.length)this.closed.add(n.key)});this.visibility()}
setData(data,opt={}){let ids=opt.preserveSelection===false?[]:this.getSelectedIds();this.setModel(data);this.load(ids);this.manual.clear();this.closed.clear();this.draw();this.changed()}
destroy(){this.el.replaceChildren();this.el.classList.remove("mts");this.map.clear()}}
class CheckboxTree extends TreeSelect{constructor(el,o={}){super(el,{...o,mode:"checkbox"})}}
class RadioTree extends TreeSelect{constructor(el,o={}){super(el,{...o,mode:"radio"})}}
g.TreeSelect=TreeSelect;g.CheckboxTree=CheckboxTree;g.RadioTree=RadioTree})(window);
